/bin/bash -lc "python3 - <<'PY'
import pathlib
import subprocess
import tempfile

source = r'''
#include \"service.hpp\"
#include <cassert>
#include <string>
int main() {
    for (int port = 1; port <= 65535; ++port) {
        const auto text = std::to_string(port);
        assert(parsePort(text) == port);
        assert(parsePort(\"000\" + text) == port);
    }
    for (const auto& text : {\"\", \"0\", \"000\", \"65536\", \"2147483647\", \"2147483648\", \"+1\", \"-1\", \" 1\", \"1 \", \"1\\n\", \"1.0\", \"0x10\", \"1x\"})
        assert(parsePort(text) == -1);
    assert(parsePort(std::string(10000, '9')) == -1);
    assert(parsePort(std::string(10000, '0') + \"65535\") == 65535);
    for (int byte = 0; byte <= 255; ++byte) {
        if (byte >= '0' && byte <= '9') continue;
        assert(parsePort(std::string(\"1\") + static_cast<char>(byte)) == -1);
    }
}
'''
with tempfile.TemporaryDirectory(prefix='parse-port-') as directory:
    executable = str(pathlib.Path(directory) / 'verify')
    subprocess.run(['c++', '-std=c++17', '-Wall', '-Wextra', '-Werror', '-fsanitize=undefined', '-fno-sanitize-recover=all', '-I.', '-x', 'c++', '-', '-o', executable], input=source, text=True, check=True)
    subprocess.run([executable], check=True)
print('Exhaustive valid ports and malformed/overflow checks passed with UBSan.')
PY"

